import React, { useState } from 'react';

// Create the Wizard component here
const Wizard = () => {
  // Add currentStep state here
  const [currentStep, setCurrentStep] = useState(0);

  // Define the steps array here
  const steps = [
    { id: 1, title: 'Step 1', condition: () => true },
    { id: 2, title: 'Step 2', condition: () => true },
    { id: 3, title: 'Step 3', condition: () => true }
  ];

  // Create shouldShowStep function here
  const shouldShowStep = (step) => {
    return step.condition();
  };

  // Create getVisibleSteps function here
  const getVisibleSteps = () => {
    return steps.filter(step => shouldShowStep(step));
  };

  // Create nextStep function here
  const nextStep = () => {
    const visibleSteps = getVisibleSteps();
    if (currentStep < visibleSteps.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  return (
    <div>
      <h2>Wizard Engine</h2>
      <div>
        Current Step: {getVisibleSteps()[currentStep]?.title || 'None'}
      </div>
      <div>
        <button onClick={prevStep}>Previous</button>
        <button onClick={nextStep}>Next</button>
      </div>
    </div>
  );
};
